class Solution {
public:
    string answerString(string word, int numFriends) {
        int n = word.size();
        if (numFriends == 1) return word;
        int i = 0, j = 1, k = 0;
        while (j + k < n) {
            if (word[i + k] == word[j + k]) {
                k++;
            } else if (word[i + k] < word[j + k]) {
                i = max(i + k + 1, j);
                j = i + 1;
                k = 0;
            } else {
                j = j + k + 1;
                k = 0;
            }
        }
        int len = min(n - numFriends + 1, n - i);
        return word.substr(i, len);
    }
};
